import type { SiteConfig } from './template';
import type { Page } from './types';

export interface SsgContext {
  contentDir: string;
  outputDir: string;
  siteConfig: SiteConfig;
  pages: Page[];
  options: Record<string, unknown>;
}

export interface Plugin {
  readonly name: string;
  onStart?(context: SsgContext): void | Promise<void>;
  beforeBuild?(context: SsgContext): void | Promise<void>;
  afterBuild?(context: SsgContext): void | Promise<void>;
  onFile?(page: Page, context: SsgContext): void | Promise<void>;
  onEnd?(context: SsgContext): void | Promise<void>;
}

export type PluginHookName =
  | 'onStart'
  | 'beforeBuild'
  | 'afterBuild'
  | 'onFile'
  | 'onEnd';

export class PluginPipeline {
  private readonly plugins: Plugin[];

  constructor(plugins: Plugin[]) {
    this.plugins = plugins;
  }

  getPlugins(): Plugin[] {
    return this.plugins;
  }

  get length(): number {
    return this.plugins.length;
  }

  async onStart(context: SsgContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onStart) await plugin.onStart(context);
    }
  }

  async beforeBuild(context: SsgContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.beforeBuild) await plugin.beforeBuild(context);
    }
  }

  async afterBuild(context: SsgContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.afterBuild) await plugin.afterBuild(context);
    }
  }

  async onFile(page: Page, context: SsgContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onFile) await plugin.onFile(page, context);
    }
  }

  async onEnd(context: SsgContext): Promise<void> {
    for (const plugin of this.plugins) {
      if (plugin.onEnd) await plugin.onEnd(context);
    }
  }
}

import { markdownToHtml } from '../markdown';
import type { Plugin, SsgContext } from '../plugin';
import type { Page } from '../types';

export class MarkdownPlugin implements Plugin {
  readonly name = 'markdown';

  async onFile(page: Page, _context: SsgContext): Promise<void> {
    page.html = await markdownToHtml(page.content);
  }
}

import * as fs from 'fs';
import * as path from 'path';
import type { Plugin, SsgContext } from '../plugin';
import { renderIndex, renderPage, type SiteConfig } from '../template';
import type { Page } from '../types';

export class TemplatePlugin implements Plugin {
  readonly name = 'template';

  async onFile(page: Page, context: SsgContext): Promise<void> {
    const config: SiteConfig = context.siteConfig;
    const html = renderPage(page, config);
    fs.mkdirSync(path.dirname(page.outputPath), { recursive: true });
    fs.writeFileSync(page.outputPath, html, 'utf8');
  }

  async afterBuild(context: SsgContext): Promise<void> {
    const config: SiteConfig = context.siteConfig;
    fs.mkdirSync(context.outputDir, { recursive: true });
    fs.writeFileSync(
      path.join(context.outputDir, 'index.html'),
      renderIndex(context.pages, config),
      'utf8'
    );
  }
}

import * as fs from 'fs';
import * as path from 'path';
import type { Plugin } from './plugin';
import { MarkdownPlugin } from './plugins/markdown-plugin';
import { TemplatePlugin } from './plugins/template-plugin';

export const DEFAULT_CONFIG_FILE = 'ssg.config.ts';

export interface SsgConfig {
  plugins: Plugin[];
  [key: string]: unknown;
}

export function builtinPlugins(): Plugin[] {
  return [new MarkdownPlugin(), new TemplatePlugin()];
}

function normalizeConfig(loaded: unknown): SsgConfig {
  const config = (loaded && typeof loaded === 'object' && 'default' in (loaded as Record<string, unknown>)
    ? (loaded as Record<string, unknown>).default
    : loaded) as Record<string, unknown> | null | undefined;

  const rawPlugins = config && Array.isArray(config.plugins) ? config.plugins : [];
  const plugins: Plugin[] = rawPlugins.filter(
    (plugin): plugin is Plugin => typeof plugin === 'object' && plugin !== null && typeof (plugin as Plugin).name === 'string'
  );

  return { ...(config ?? {}), plugins: plugins.length > 0 ? plugins : builtinPlugins() };
}

export async function loadConfig(configPath?: string): Promise<SsgConfig> {
  const resolved = configPath
    ? path.resolve(configPath)
    : path.resolve(process.cwd(), DEFAULT_CONFIG_FILE);

  if (!fs.existsSync(resolved)) {
    return { plugins: builtinPlugins() };
  }

  try {
    return normalizeConfig(require(resolved));
  } catch {
    const jsPath = resolved.endsWith('.ts') ? `${resolved.slice(0, -3)}.js` : null;
    if (jsPath && fs.existsSync(jsPath)) {
      try {
        return normalizeConfig(require(jsPath));
      } catch {
        // fall through to built-ins below
      }
    }
    console.warn(`Failed to load config from ${resolved}; using built-in plugins`);
    return { plugins: builtinPlugins() };
  }
}

export async function loadPlugins(configPath?: string): Promise<Plugin[]> {
  const config = await loadConfig(configPath);
  return Array.isArray(config.plugins) && config.plugins.length > 0
    ? config.plugins
    : builtinPlugins();
}

import * as fs from 'fs';
import * as path from 'path';
import { loadPlugins } from './config';
import { parseFrontmatter } from './frontmatter';
import { PluginPipeline, type Plugin, type SsgContext } from './plugin';
import type { SiteConfig } from './template';
import type { Page } from './types';

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
  siteTitle?: string;
  templatesDir?: string;
  defaultTemplate?: string;
  defaultLayout?: string;
  configPath?: string;
}

export const DEFAULT_CONTENT_DIR = './content';
export const DEFAULT_OUTPUT_DIR = './dist';
export const DEFAULT_TEMPLATES_DIR = './templates';
export const DEFAULT_SITE_TITLE = 'My Static Site';

const MARKDOWN_EXTENSION = /\.(md|markdown)$/i;

export function collectMarkdownFiles(contentDir: string): string[] {
  if (!fs.existsSync(contentDir)) return [];

  const files: string[] = [];
  const walk = (dir: string): void => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(full);
      } else if (entry.isFile() && MARKDOWN_EXTENSION.test(entry.name)) {
        files.push(full);
      }
    }
  };
  walk(contentDir);
  return files.sort();
}

export function slugFor(filePath: string, contentDir: string): string {
  const relative = path.relative(contentDir, filePath).replace(/\\/g, '/');
  return relative.replace(MARKDOWN_EXTENSION, '');
}

function toSiteConfig(options: BuildOptions): SiteConfig {
  return {
    title: options.siteTitle ?? DEFAULT_SITE_TITLE,
    templatesDir: options.templatesDir ? path.resolve(options.templatesDir) : path.resolve(DEFAULT_TEMPLATES_DIR),
    defaultTemplate: options.defaultTemplate,
    defaultLayout: options.defaultLayout,
  };
}

function createContext(options: BuildOptions): SsgContext {
  return {
    contentDir: path.resolve(options.contentDir),
    outputDir: path.resolve(options.outputDir),
    siteConfig: toSiteConfig(options),
    pages: [],
    options: { ...options },
  };
}

export class Ssg {
  private readonly pipeline: PluginPipeline;

  constructor(plugins: Plugin[]) {
    this.pipeline = new PluginPipeline(plugins);
  }

  static async create(options: { plugins?: Plugin[]; configPath?: string } = {}): Promise<Ssg> {
    const plugins = options.plugins ?? (await loadPlugins(options.configPath));
    return new Ssg(plugins);
  }

  getPlugins(): Plugin[] {
    return this.pipeline.getPlugins();
  }

  build(options: BuildOptions): Promise<Page[]> {
    return this.run(options, true);
  }

  rebuild(options: BuildOptions): Promise<Page[]> {
    return this.run(options, false);
  }

  private async run(options: BuildOptions, runStart: boolean): Promise<Page[]> {
    const context = createContext(options);

    if (runStart) {
      await this.pipeline.onStart(context);
    }
    await this.pipeline.beforeBuild(context);

    for (const file of collectMarkdownFiles(context.contentDir)) {
      const source = fs.readFileSync(file, 'utf8');
      const { data, content } = parseFrontmatter(source);
      const slug = slugFor(file, context.contentDir);
      const page: Page = {
        slug,
        link: `${slug}.html`,
        outputPath: path.join(context.outputDir, `${slug}.html`),
        filePath: file,
        data,
        content,
        html: '',
        template: data.template,
        layout: data.layout,
      };
      context.pages.push(page);
      await this.pipeline.onFile(page, context);
    }

    fs.mkdirSync(context.outputDir, { recursive: true });
    await this.pipeline.afterBuild(context);
    await this.pipeline.onEnd(context);

    return context.pages;
  }
}

export async function buildSite(options: BuildOptions): Promise<Page[]> {
  const engine = await Ssg.create({ configPath: options.configPath });
  return engine.build(options);
}

import * as http from 'http';
import * as fs from 'fs';
import * as path from 'path';
import chokidar from 'chokidar';
import { WebSocketServer } from 'ws';
import { loadPlugins } from '../config';
import type { Plugin, SsgContext } from '../plugin';
import { Ssg, DEFAULT_CONTENT_DIR, DEFAULT_OUTPUT_DIR, DEFAULT_TEMPLATES_DIR } from '../ssg';
import type { BuildOptions } from '../ssg';
import type { Page } from '../types';

export interface DevServerOptions extends BuildOptions {
  port: number;
  host?: string;
  rebuildDelay?: number;
}

export interface DevServerInstance {
  server: http.Server;
  wss: WebSocketServer;
  port: number;
  outputDir: string;
  rebuild: () => Promise<number>;
  broadcast: (message: string) => void;
  close: () => Promise<void>;
}

export const DEFAULT_PORT = 3000;
export const DEFAULT_HOST = 'localhost';
export const WS_PATH = '/live-reload';

const LIVE_RELOAD_SCRIPT = [
  '<script>',
  '(function () {',
  '  var protocol = location.protocol === "https:" ? "wss:" : "ws:";',
  `  var socket = new WebSocket(protocol + "//" + location.host + "${WS_PATH}");`,
  '  socket.onmessage = function (event) {',
  '    if (event.data === "reload") {',
  '      location.reload();',
  '    }',
  '  };',
  '  socket.onclose = function () {',
  '    setTimeout(function () { location.reload(); }, 1000);',
  '  };',
  '})();',
  '</script>',
].join('\n');

export function injectLiveReloadScript(html: string): string {
  if (html.toLowerCase().includes('</body>')) {
    return html.replace(/<\/body>/i, `${LIVE_RELOAD_SCRIPT}\n</body>`);
  }
  if (html.toLowerCase().includes('</html>')) {
    return html.replace(/<\/html>/i, `${LIVE_RELOAD_SCRIPT}\n</html>`);
  }
  return `${html}\n${LIVE_RELOAD_SCRIPT}`;
}

function mimeType(filePath: string): string {
  const ext = path.extname(filePath).toLowerCase();
  switch (ext) {
    case '.html':
      return 'text/html; charset=utf-8';
    case '.css':
      return 'text/css; charset=utf-8';
    case '.js':
    case '.mjs':
      return 'application/javascript; charset=utf-8';
    case '.json':
      return 'application/json; charset=utf-8';
    case '.png':
      return 'image/png';
    case '.jpg':
    case '.jpeg':
      return 'image/jpeg';
    case '.gif':
      return 'image/gif';
    case '.svg':
      return 'image/svg+xml';
    case '.ico':
      return 'image/x-icon';
    case '.woff':
      return 'font/woff';
    case '.woff2':
      return 'font/woff2';
    default:
      return 'application/octet-stream';
  }
}

function createRequestHandler(outputDir: string): http.RequestListener {
  const resolvedOutputDir = path.resolve(outputDir);

  return (req: http.IncomingMessage, res: http.ServerResponse): void => {
    let urlPath = '/';
    try {
      urlPath = decodeURIComponent((req.url ?? '/').split('?')[0]);
    } catch {
      urlPath = '/';
    }

    let filePath = path.join(resolvedOutputDir, urlPath);
    const isDirectoryRequest = filePath.endsWith(path.sep) || filePath === resolvedOutputDir;
    if (isDirectoryRequest) {
      filePath = path.join(resolvedOutputDir, 'index.html');
    }

    const resolved = path.resolve(filePath);
    if (resolved !== resolvedOutputDir && !resolved.startsWith(resolvedOutputDir + path.sep)) {
      res.writeHead(403, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Forbidden');
      return;
    }

    const serveIndex = (): void => {
      const index = path.join(resolvedOutputDir, 'index.html');
      if (fs.existsSync(index)) {
        const html = injectLiveReloadScript(fs.readFileSync(index, 'utf8'));
        res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
        res.end(html);
        return;
      }
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
    };

    if (!fs.existsSync(resolved) || !fs.statSync(resolved).isFile()) {
      if (!isDirectoryRequest && path.extname(urlPath) === '') {
        serveIndex();
        return;
      }
      res.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      res.end('Not Found');
      return;
    }

    const contentType = mimeType(resolved);
    const isText = contentType.startsWith('text/') || contentType === 'image/svg+xml';
    if (isText) {
      let text = fs.readFileSync(resolved, 'utf8');
      if (resolved.endsWith('.html')) {
        text = injectLiveReloadScript(text);
      }
      res.writeHead(200, { 'Content-Type': contentType });
      res.end(text);
      return;
    }

    res.writeHead(200, { 'Content-Type': contentType });
    res.end(fs.readFileSync(resolved));
  };
}

export class DevServerPlugin implements Plugin {
  readonly name = 'dev-server';

  private readonly options: DevServerOptions;
  private readonly engine: Ssg;
  private readonly buildPlugins: Plugin[];

  private server: http.Server | null = null;
  private wss: WebSocketServer | null = null;
  private watcher: ReturnType<typeof chokidar.watch> | null = null;
  private debounceTimer: NodeJS.Timeout | null = null;
  private closed = false;
  private actualPort = 0;
  private outputDir = '';
  private context: SsgContext | null = null;

  constructor(options: DevServerOptions, buildPlugins: Plugin[]) {
    this.options = options;
    this.buildPlugins = buildPlugins;
    this.engine = new Ssg(buildPlugins);
  }

  getPlugins(): Plugin[] {
    return this.buildPlugins;
  }

  async onStart(context: SsgContext): Promise<void> {
    this.context = context;
    this.outputDir = context.outputDir;
  }

  async onEnd(_context: SsgContext): Promise<void> {
    // Server lifecycle is managed via start()/close().
  }

  async start(): Promise<DevServerInstance> {
    const contentDir = path.resolve(this.options.contentDir ?? DEFAULT_CONTENT_DIR);
    const outputDir = path.resolve(this.options.outputDir ?? DEFAULT_OUTPUT_DIR);
    const templatesDir = this.options.templatesDir
      ? path.resolve(this.options.templatesDir)
      : path.resolve(DEFAULT_TEMPLATES_DIR);
    const host = this.options.host ?? DEFAULT_HOST;
    const rebuildDelay = this.options.rebuildDelay ?? 100;
    this.outputDir = outputDir;

    const buildOptions: BuildOptions = {
      contentDir,
      outputDir,
      templatesDir,
      siteTitle: this.options.siteTitle,
      defaultTemplate: this.options.defaultTemplate,
      defaultLayout: this.options.defaultLayout,
    };
    this.buildOptions = buildOptions;

    this.server = http.createServer(createRequestHandler(outputDir));
    this.wss = new WebSocketServer({ server: this.server, path: WS_PATH });

    await this.rebuild();

    this.watcher = chokidar.watch([contentDir, templatesDir], {
      ignoreInitial: true,
      persistent: true,
    });
    this.watcher.on('all', (event, changePath) => {
      if (this.closed) return;
      console.log(`${event}: ${changePath}`);
      this.scheduleRebuild(rebuildDelay);
    });
    await new Promise<void>((resolve) => this.watcher!.once('ready', () => resolve()));

    await new Promise<void>((resolve, reject) => {
      this.server!.once('error', reject);
      this.server!.listen(this.options.port, host, () => {
        this.server!.removeListener('error', reject);
        resolve();
      });
    });

    const address = this.server!.address();
    this.actualPort = address && typeof address === 'object' ? address.port : this.options.port;

    return this.instance();
  }

  private buildOptions: BuildOptions | null = null;

  async rebuild(): Promise<number> {
    if (!this.buildOptions) return 0;
    const pages: Page[] = await this.engine.rebuild(this.buildOptions);
    return pages.length;
  }

  broadcast(message: string): void {
    if (this.closed || !this.wss) return;
    for (const client of this.wss.clients) {
      if (client.readyState === client.OPEN) {
        client.send(message);
      }
    }
  }

  async close(): Promise<void> {
    this.closed = true;
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = null;
    }
    if (this.watcher) {
      await this.watcher.close();
    }
    if (this.wss) {
      for (const client of this.wss.clients) {
        client.terminate();
      }
      await new Promise<void>((resolve) => this.wss!.close(() => resolve()));
    }
    if (this.server) {
      await new Promise<void>((resolve) => this.server!.close(() => resolve()));
    }
  }

  private scheduleRebuild(rebuildDelay: number): void {
    if (this.closed) return;
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
    }
    this.debounceTimer = setTimeout(() => {
      this.debounceTimer = null;
      if (this.closed) return;
      this.rebuild()
        .then((count) => {
          console.log(`Rebuilt ${count} page(s)`);
          this.broadcast('reload');
        })
        .catch((error) => {
          console.error(`Rebuild failed: ${(error as Error).message}`);
        });
    }, rebuildDelay);
  }

  private instance(): DevServerInstance {
    return {
      server: this.server!,
      wss: this.wss!,
      port: this.actualPort,
      outputDir: this.outputDir,
      rebuild: () => this.rebuild(),
      broadcast: (message: string) => this.broadcast(message),
      close: () => this.close(),
    };
  }
}

export async function startDevServer(options: DevServerOptions): Promise<DevServerInstance> {
  const plugins = await loadPlugins(options.configPath);
  const plugin = new DevServerPlugin(options, plugins);
  return await plugin.start();
}

