import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import { PluginPipeline } from '../src/plugin';
import type { Plugin, SsgContext } from '../src/plugin';
import { MarkdownPlugin } from '../src/plugins/markdown-plugin';
import { TemplatePlugin } from '../src/plugins/template-plugin';
import { DevServerPlugin } from '../src/plugins/dev-server-plugin';
import { builtinPlugins, loadPlugins } from '../src/config';
import { Ssg, buildSite } from '../src/ssg';

describe('plugin system', () => {
  it('runs hooks in registration order', async () => {
    const order: string[] = [];
    const p1: Plugin = {
      name: 'one',
      onStart: () => { order.push('one.onStart'); },
      beforeBuild: () => { order.push('one.beforeBuild'); },
      afterBuild: () => { order.push('one.afterBuild'); },
      onEnd: () => { order.push('one.onEnd'); },
    };
    const p2: Plugin = {
      name: 'two',
      onStart: () => { order.push('two.onStart'); },
      beforeBuild: () => { order.push('two.beforeBuild'); },
      afterBuild: () => { order.push('two.afterBuild'); },
      onEnd: () => { order.push('two.onEnd'); },
    };
    const pipeline = new PluginPipeline([p1, p2]);
    const ctx = { contentDir: 'c', outputDir: 'o', siteConfig: { title: 't' }, pages: [], options: {} } as SsgContext;
    await pipeline.onStart(ctx);
    await pipeline.beforeBuild(ctx);
    await pipeline.afterBuild(ctx);
    await pipeline.onEnd(ctx);
    expect(order).toEqual([
      'one.onStart', 'two.onStart',
      'one.beforeBuild', 'two.beforeBuild',
      'one.afterBuild', 'two.afterBuild',
      'one.onEnd', 'two.onEnd',
    ]);
  });

  it('exposes lifecycle hooks as a Plugin', () => {
    const plugin = new MarkdownPlugin();
    expect(plugin.name).toBe('markdown');
    expect(typeof plugin.onFile).toBe('function');
    expect(new TemplatePlugin().name).toBe('template');
    const dev = new DevServerPlugin({ port: 0, contentDir: 'c', outputDir: 'o' }, builtinPlugins());
    expect(dev.name).toBe('dev-server');
    expect(typeof dev.onStart).toBe('function');
    expect(typeof dev.rebuild).toBe('function');
    expect(typeof dev.close).toBe('function');
  });

  it('loads plugins from ssg.config.ts', async () => {
    const plugins = await loadPlugins();
    expect(plugins.map((p) => p.name)).toEqual(['markdown', 'template', 'example']);
  });

  it('builds a site through the engine pipeline', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-plugin-'));
    try {
      const contentDir = path.join(tmp, 'content');
      const outputDir = path.join(tmp, 'dist');
      fs.mkdirSync(contentDir, { recursive: true });
      fs.writeFileSync(path.join(contentDir, 'page.md'), '---\ntitle: P\n---\n\n# Body');
      const engine = await Ssg.create({ plugins: [new MarkdownPlugin(), new TemplatePlugin()] });
      const pages = await engine.build({ contentDir, outputDir });
      expect(pages).toHaveLength(1);
      expect(fs.existsSync(path.join(outputDir, 'page.html'))).toBe(true);
      expect(fs.existsSync(path.join(outputDir, 'index.html'))).toBe(true);
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });

  it('buildSite picks up a custom plugin', async () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-plugin-'));
    try {
      const contentDir = path.join(tmp, 'content');
      const outputDir = path.join(tmp, 'dist');
      fs.mkdirSync(contentDir, { recursive: true });
      fs.writeFileSync(path.join(contentDir, 'a.md'), '# A');
      const marker: Plugin = {
        name: 'marker',
        onFile: (page) => { page.data.title = 'MUTATED'; },
      };
      const pages = await buildSite({ contentDir, outputDir, plugins: [new MarkdownPlugin(), marker, new TemplatePlugin()] });
      expect(pages[0].data.title).toBe('MUTATED');
    } finally {
      fs.rmSync(tmp, { recursive: true, force: true });
    }
  });
});

